#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <mongoc/mongoc.h>

#define POOL_SIZE 8
#define MAX_FIELD_LEN 256
#define QUERY_BUF_SIZE 2048

typedef struct {
    mongoc_client_t *clients[POOL_SIZE];
    int available[POOL_SIZE];
    pthread_mutex_t lock;
} connection_pool_t;

static connection_pool_t g_pool;

void pool_init(const char *uri_str) {
    pthread_mutex_init(&g_pool.lock, NULL);
    for (int i = 0; i < POOL_SIZE; i++) {
        g_pool.clients[i] = mongoc_client_new(uri_str);
        g_pool.available[i] = 1;
    }
}

mongoc_client_t *pool_acquire(void) {
    pthread_mutex_lock(&g_pool.lock);
    for (int i = 0; i < POOL_SIZE; i++) {
        if (g_pool.available[i]) {
            g_pool.available[i] = 0;
            pthread_mutex_unlock(&g_pool.lock);
            return g_pool.clients[i];
        }
    }
    pthread_mutex_unlock(&g_pool.lock);
    return NULL;
}

void pool_release(mongoc_client_t *client) {
    pthread_mutex_lock(&g_pool.lock);
    for (int i = 0; i < POOL_SIZE; i++) {
        if (g_pool.clients[i] == client) {
            g_pool.available[i] = 1;
            break;
        }
    }
    pthread_mutex_unlock(&g_pool.lock);
}

/* Sanitize a value by escaping special characters for string context */
static int sanitize_value(const char *input, char *output, size_t outlen) {
    size_t j = 0;
    for (size_t i = 0; input[i] && j < outlen - 2; i++) {
        if (input[i] == '"' || input[i] == '\\') {
            output[j++] = '\\';
            output[j++] = input[i];
        } else if (input[i] < 0x20) {
            /* skip control characters */
            continue;
        } else {
            output[j++] = input[i];
        }
    }
    output[j] = '\0';
    return 0;
}

/* Validate field name - only allow alphanumeric and underscore */
static int validate_field_name(const char *field) {
    for (size_t i = 0; field[i]; i++) {
        char c = field[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '_')) {
            return -1;
        }
    }
    return 0;
}

/* Build a query filter from user-supplied search parameters.
 * Parameters come as key=value pairs in a structured request. */
typedef struct {
    char field[MAX_FIELD_LEN];
    char value[MAX_FIELD_LEN];
    char op[16]; /* eq, ne, gt, lt, regex */
} search_param_t;

static bson_t *build_query_filter(search_param_t *params, int param_count) {
    char query_json[QUERY_BUF_SIZE];
    int offset = 0;

    offset += snprintf(query_json + offset, QUERY_BUF_SIZE - offset, "{");

    for (int i = 0; i < param_count; i++) {
        char sanitized_value[MAX_FIELD_LEN * 2];

        if (validate_field_name(params[i].field) != 0) {
            return NULL;
        }

        sanitize_value(params[i].value, sanitized_value, sizeof(sanitized_value));

        if (i > 0) {
            offset += snprintf(query_json + offset, QUERY_BUF_SIZE - offset, ", ");
        }

        if (strcmp(params[i].op, "eq") == 0) {
            offset += snprintf(query_json + offset, QUERY_BUF_SIZE - offset,
                "\"%s\": \"%s\"", params[i].field, sanitized_value);
        } else if (strcmp(params[i].op, "ne") == 0) {
            offset += snprintf(query_json + offset, QUERY_BUF_SIZE - offset,
                "\"%s\": {\"$ne\": \"%s\"}", params[i].field, sanitized_value);
        } else if (strcmp(params[i].op, "gt") == 0) {
            offset += snprintf(query_json + offset, QUERY_BUF_SIZE - offset,
                "\"%s\": {\"$gt\": \"%s\"}", params[i].field, sanitized_value);
        } else if (strcmp(params[i].op, "lt") == 0) {
            offset += snprintf(query_json + offset, QUERY_BUF_SIZE - offset,
                "\"%s\": {\"$lt\": \"%s\"}", params[i].field, sanitized_value);
        } else if (strcmp(params[i].op, "regex") == 0) {
            offset += snprintf(query_json + offset, QUERY_BUF_SIZE - offset,
                "\"%s\": {\"$regex\": \"%s\"}", params[i].field, sanitized_value);
        } else {
            return NULL;
        }
    }

    offset += snprintf(query_json + offset, QUERY_BUF_SIZE - offset, "}");

    bson_error_t error;
    bson_t *filter = bson_new_from_json((const uint8_t *)query_json, -1, &error);
    return filter;
}

/* Parse the operator from request - the op field is taken from a
 * pre-validated enum on the frontend, but we re-validate here */
static int parse_operator(const char *raw_op, char *out_op, size_t outlen) {
    const char *allowed[] = {"eq", "ne", "gt", "lt", "regex", NULL};
    /* Normalize: trim and lowercase */
    char normalized[16] = {0};
    size_t len = strlen(raw_op);
    if (len >= sizeof(normalized)) return -1;

    for (size_t i = 0; i < len; i++) {
        normalized[i] = raw_op[i] | 0x20; /* tolower for ASCII alpha */
    }

    for (int i = 0; allowed[i]; i++) {
        if (strcmp(normalized, allowed[i]) == 0) {
            strncpy(out_op, normalized, outlen - 1);
            out_op[outlen - 1] = '\0';
            return 0;
        }
    }
    return -1;
}

char *execute_search(const char *collection_name, search_param_t *params,
                     int param_count) {
    if (validate_field_name(collection_name) != 0) {
        return NULL;
    }

    mongoc_client_t *client = pool_acquire();
    if (!client) return NULL;

    mongoc_collection_t *collection =
        mongoc_client_get_collection(client, "appdb", collection_name);

    bson_t *filter = build_query_filter(params, param_count);
    if (!filter) {
        mongoc_collection_destroy(collection);
        pool_release(client);
        return NULL;
    }

    mongoc_cursor_t *cursor = mongoc_collection_find_with_opts(
        collection, filter, NULL, NULL);

    char *result = malloc(65536);
    int roff = 0;
    roff += snprintf(result + roff, 65536 - roff, "[");

    const bson_t *doc;
    int first = 1;
    while (mongoc_cursor_next(cursor, &doc)) {
        char *json = bson_as_json(doc, NULL);
        if (!first) roff += snprintf(result + roff, 65536 - roff, ",");
        roff += snprintf(result + roff, 65536 - roff, "%s", json);
        bson_free(json);
        first = 0;
    }
    roff += snprintf(result + roff, 65536 - roff, "]");

    mongoc_cursor_destroy(cursor);
    bson_destroy(filter);
    mongoc_collection_destroy(collection);
    pool_release(client);

    return result;
}

